package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.concurrent.CopyOnWriteArrayList;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.backup.BackupRequest;
import org.eclipse.rdf4j.sail.backup.BackupType;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

@Timeout(30)
class LmdbBackupSteadyStateSyncTest {

	@Test
	void durableNativeCommitDoesNotRepeatExplicitSyncForPublication(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setBackupJournalEnabled(true);
		assertFalse(config.getForceSync());
		LmdbStore store = new LmdbStore(directory.resolve("live").toFile(), config);
		store.init();
		try {
			Path backups = directory.resolve("backups");
			long baseline = store.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.FULL).build())
					.getEndTransactionId();
			var syncs = new CopyOnWriteArrayList<String>();
			store.getBackingStore()
					.valueStore()
					.setBeforeBackupSync(() -> syncs.add("values on " + Thread.currentThread().getName()));
			store.getBackingStore()
					.getTripleStore()
					.setBeforeBackupSync(() -> syncs.add("triples on " + Thread.currentThread().getName()));
			var values = SimpleValueFactory.getInstance();
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(values.createIRI("urn:new:sync-subject"),
						values.createIRI("urn:new:sync-predicate"),
						values.createLiteral("fresh-dictionary-term-".repeat(40)));
				connection.commit();
			}
			assertEquals(baseline + 1, store.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
							.sinceTransactionId(baseline)
							.build())
					.getEndTransactionId());
			assertTrue(syncs.isEmpty(),
					() -> "Publication must not repeat already durable native commit syncs: " + syncs);
		} finally {
			store.shutDown();
		}
	}
}
